/**
 * 支付回调验签。
 *
 * <p>新签名使用 HMAC-SHA256，并把 Unix 时间戳放进签名串，默认只接受
 * {@code renewal.callback.timestamp-tolerance-seconds} 时间窗内的回调，降低重放风险。
 * 签名格式为 {@code v2:<timestamp>:<hex-hmac>}，HMAC 的消息为
 * {@code externalTxnId + ":" + amountCents + ":" + timestamp}。
 *
 * <p>为了不影响线上老回调，过渡期内仍接受旧格式
 * {@code MD5(externalTxnId + ":" + amountCents + ":" + legacySecret)}。
 * 老签名不包含时间戳，因此没有时间窗校验；确认老流量下线后，把
 * {@code renewal.callback.legacy-enabled} 置为 {@code false} 即可彻底关闭。
 *
 * <p>密钥不再硬编码在验签逻辑里，而是来自配置/环境变量：
 * {@code renewal.callback.secret}、{@code renewal.callback.legacy-secret}。
 * {@code legacy-secret} 支持逗号分隔多把密钥，便于滚动轮换；当前密钥也会作为
 * 老签名候选密钥参与校验。
 */
@Component
public class SignatureVerifier {

    /** 仅用于本地开发和默认测试；生产必须通过环境变量/配置覆盖。 */
    private static final String DEFAULT_DEV_SECRET = "dev-secret-do-not-use-in-prod";
    private static final long DEFAULT_TIMESTAMP_TOLERANCE_SECONDS = 300L;
    private static final String V2_PREFIX = "v2:";
    private static final String MD5_PREFIX = "md5:";
    private static final String V1_PREFIX = "v1:";
    private static final long MILLIS_THRESHOLD = 100_000_000_000L;

    private final String secret;
    private final List<String> legacySecrets;
    private final boolean legacyEnabled;
    private final long timestampToleranceSeconds;
    private final Clock clock;

    /** 兼容既有单测/手工构造：使用默认开发密钥和系统时钟。 */
    public SignatureVerifier() {
        this(DEFAULT_DEV_SECRET, DEFAULT_DEV_SECRET, true, DEFAULT_TIMESTAMP_TOLERANCE_SECONDS, Clock.systemUTC());
    }

    @Autowired
    public SignatureVerifier(
            @Value("${renewal.callback.secret:dev-secret-do-not-use-in-prod}") String secret,
            @Value("${renewal.callback.legacy-secret:dev-secret-do-not-use-in-prod}") String legacySecret,
            @Value("${renewal.callback.legacy-enabled:true}") boolean legacyEnabled,
            @Value("${renewal.callback.timestamp-tolerance-seconds:300}") long timestampToleranceSeconds,
            Clock clock) {
        if (secret == null || secret.isBlank()) {
            throw new IllegalArgumentException("renewal.callback.secret 不能为空");
        }
        this.secret = secret;
        this.legacySecrets = collectLegacySecrets(legacySecret, secret);
        this.legacyEnabled = legacyEnabled;
        this.timestampToleranceSeconds = Math.max(0L, timestampToleranceSeconds);
        this.clock = Objects.requireNonNull(clock, "clock");
    }

    /**
     * 用当前时间生成新格式签名。
     *
     * <p>方法签名保持不变，方便既有调用方平滑升级；返回值已从 MD5 变为
     * {@code v2:<timestamp>:<hmac-sha256>}。
     */
    public String sign(String externalTxnId, long amountCents) {
        return sign(externalTxnId, amountCents, clock.instant().getEpochSecond());
    }

    /** 用指定的 Unix 秒级时间戳生成新格式签名，便于测试和补偿任务。 */
    public String sign(String externalTxnId, long amountCents, long timestampSeconds) {
        Objects.requireNonNull(externalTxnId, "externalTxnId");
        String timestampToken = Long.toString(timestampSeconds);
        String mac = hmacSha256Hex(secret, payload(externalTxnId, amountCents, timestampToken));
        return V2_PREFIX + timestampToken + ":" + mac;
    }

    /** 生成旧版 MD5 签名，仅用于兼容性测试或尚未升级的调用方。 */
    public String signLegacy(String externalTxnId, long amountCents) {
        Objects.requireNonNull(externalTxnId, "externalTxnId");
        return md5Hex(legacySecrets.get(0), externalTxnId, amountCents);
    }

    /**
     * 验签：优先识别新格式（带时间戳的 HMAC-SHA256），否则在过渡期内回退到旧 MD5。
     */
    public boolean verify(String externalTxnId, long amountCents, String signature) {
        return verify(externalTxnId, amountCents, null, signature);
    }

    /**
     * 验签，并允许回调报文在签名串之外额外携带时间戳。
     *
     * <p>如果签名串本身带时间戳，{@code timestamp} 必须与之一致；如果签名串是
     * 裸 HMAC（{@code v2:<hmac>} 或 64 位 hex），则必须提供 {@code timestamp}。
     */
    public boolean verify(String externalTxnId, long amountCents, Long timestamp, String signature) {
        if (externalTxnId == null || signature == null || signature.isBlank()) {
            return false;
        }
