/** R3 验签升级：新 HMAC-SHA256 + 时间戳，同时兼容旧 MD5 回调。 */
class SignatureVerifierUpgradeTest {

    private static final Clock FIXED_CLOCK = Clock.fixed(Instant.parse("2025-12-01T00:00:00Z"), ZoneOffset.UTC);
    private static final long NOW = FIXED_CLOCK.instant().getEpochSecond();

    @Test
    void newSignatureUsesTimestampedHmacSha256() {
        SignatureVerifier verifier = new SignatureVerifier("unit-test-secret", FIXED_CLOCK);

        String signature = verifier.sign("TXN-1", 9900L);

        assertTrue(signature.startsWith("v2:" + NOW + ":"));
        assertTrue(verifier.verify("TXN-1", 9900L, signature));
        assertFalse(verifier.verify("TXN-1", 9901L, signature));
        assertFalse(verifier.verify("TXN-2", 9900L, signature));
    }

    @Test
    void timestampOutsideToleranceIsRejected() {
        SignatureVerifier verifier = new SignatureVerifier("unit-test-secret", FIXED_CLOCK);

        assertTrue(verifier.verify("TXN-1", 9900L, verifier.sign("TXN-1", 9900L, NOW - 300L)));
        assertFalse(verifier.verify("TXN-1", 9900L, verifier.sign("TXN-1", 9900L, NOW - 301L)));
        assertFalse(verifier.verify("TXN-1", 9900L, verifier.sign("TXN-1", 9900L, NOW + 301L)));
    }

    @Test
    void legacyMd5StillWorksDuringTransition() {
        SignatureVerifier verifier = new SignatureVerifier("unit-test-secret", FIXED_CLOCK);

        String legacySignature = verifier.signLegacy("TXN-OLD", 9900L);

        assertEquals(32, legacySignature.length());
        assertTrue(verifier.verify("TXN-OLD", 9900L, legacySignature));
        assertTrue(verifier.verifyLegacy("TXN-OLD", 9900L, legacySignature));
    }

    @Test
    void legacySignatureCanBeDisabledAfterTransition() {
        SignatureVerifier verifier = new SignatureVerifier(
                "unit-test-secret", "old-unit-test-secret", false, 300L, FIXED_CLOCK);

        String legacySignature = verifier.signLegacy("TXN-OLD", 9900L);

        assertFalse(verifier.verify("TXN-OLD", 9900L, legacySignature));
    }

    @Test
    void bareHmacWithSeparateTimestampIsAccepted() {
        SignatureVerifier verifier = new SignatureVerifier("unit-test-secret", FIXED_CLOCK);
        String fullSignature = verifier.sign("TXN-1", 9900L, NOW);
        String bareHmac = fullSignature.substring(fullSignature.lastIndexOf(':') + 1);

        assertTrue(verifier.verify("TXN-1", 9900L, NOW, bareHmac));
        assertFalse(verifier.verify("TXN-1", 9900L, NOW + 1L, bareHmac));
        assertFalse(verifier.verify("TXN-1", 9900L, (Long) null, bareHmac));
    }
